            subtotalProdutos,
            descontoCupom,
            frete,
            modalidade.prazoEmDias(),
            seguro,
            ajustePagamento,
            totalFinal,
            numeroParcelasFinal,
            valorParcela,
            creditoProximaCompra,
            brinde
        );
    }

    private void validarPedido(PedidoRequest request) {
        if (request.itens() == null || request.itens().isEmpty()) {
